import{_ as a,o as i,c as o,a2 as s}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Estándares de Expertos Supremos de Planos","description":"","frontmatter":{},"headers":[],"relativePath":"es/17-位面至高强者标准.md","filePath":"es/17-位面至高强者标准.md","lastUpdated":null}'),n={name:"es/17-位面至高强者标准.md"};function l(d,e,r,t,c,u){return i(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="estandares-de-expertos-supremos-de-planos" tabindex="-1">Estándares de Expertos Supremos de Planos <a class="header-anchor" href="#estandares-de-expertos-supremos-de-planos" aria-label="Permalink to &quot;Estándares de Expertos Supremos de Planos&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>17</td></tr><tr><td>Módulo</td><td>Leyes Cósmicas y Sistemas de Cultivo</td></tr><tr><td>Palabras clave</td><td>Supremo de Planos, Estándares de Expertos, Activación del 20%, Nivel del Origen, Responsabilidad de los Expertos</td></tr></tbody></table><h2 id="i-definicion-y-posicionamiento-de-los-expertos-supremos-de-planos" tabindex="-1">I. Definición y Posicionamiento de los Expertos Supremos de Planos <a class="header-anchor" href="#i-definicion-y-posicionamiento-de-los-expertos-supremos-de-planos" aria-label="Permalink to &quot;I. Definición y Posicionamiento de los Expertos Supremos de Planos&quot;">​</a></h2><p>&quot;Experto Supremo de Planos&quot; es el título formal que la Civilización Simbiótica del Ancla otorga a los cultivadores que han alcanzado el nivel de poder cósmico, refiriéndose a los cultivadores de élite cuya fuerza es suficiente para sostener independientemente la estabilidad de las leyes de un plano y que pueden ejercer influencia a escala cósmica. En el estándar unificado de división de niveles, los Expertos Supremos de Planos corresponden al Noveno Nivel &quot;Nivel del Origen&quot; y superiores, el grupo de poder más supremo de Heng Yuan Zhou.</p><p>Ser un Experto Supremo de Planos no es meramente un título de nivel de poder, sino también un posicionamiento de responsabilidad e identidad. En el marco de la civilización simbiótica, cuanto mayor es el poder, mayor es la responsabilidad. Los Expertos Supremos de Planos no son solo individuos que han tenido éxito en el cultivo, sino también guardianes de la civilización, mantenedores de leyes y guías para quienes vienen después. El objetivo central de la &quot;Estrategia de Activación del 20%&quot; de la civilización simbiótica es activar, en la etapa inicial del establecimiento de la civilización, al 20% de todos los seres vivos para que alcancen el nivel de Experto Supremo de Planos, sentando la base de poder para la ascensión dimensional general del universo.</p><p>Cabe señalar especialmente que el &quot;Experto Supremo de Planos&quot; de la civilización simbiótica es esencialmente diferente del &quot;Señor de Planos&quot; de la era del depredacionismo. Los Señores de Planos de la era del depredacionismo esclavizaban los planos con el poder y saqueaban los recursos, siendo los gobernantes y saqueadores de los planos; mientras que los Expertos Supremos de Planos de la civilización simbiótica protegen los planos con el poder y sirven a todos los seres, siendo los guardianes y servidores de los planos. Esta diferencia es una manifestación directa de la filosofía central antidepredacionista de la civilización simbiótica a nivel de los fuertes.</p><h2 id="ii-estandares-de-evaluacion-de-los-expertos-supremos-de-planos" tabindex="-1">II. Estándares de Evaluación de los Expertos Supremos de Planos <a class="header-anchor" href="#ii-estandares-de-evaluacion-de-los-expertos-supremos-de-planos" aria-label="Permalink to &quot;II. Estándares de Evaluación de los Expertos Supremos de Planos&quot;">​</a></h2><p>La evaluación de los Expertos Supremos de Planos adopta el &quot;Sistema de Evaluación de Cuatro Dimensiones&quot;; solo cuando las cuatro dimensiones cumplen los estándares puede uno ser reconocido formalmente como Experto Supremo de Planos:</p><table tabindex="0"><thead><tr><th>Dimensión</th><th>Contenido de Evaluación</th><th>Estándar de Aprobación</th><th>Peso</th></tr></thead><tbody><tr><td>Dimensión de Poder</td><td>Nivel, nivel de energía, capacidad de manipulación de leyes</td><td>Alcanzar el Noveno Nivel del estándar unificado (Nivel del Origen), capaz de movilizar independientemente el poder del Origen</td><td>40%</td></tr><tr><td>Dimensión de Carácter</td><td>Madurez mental, adhesión ética, postura antidepredacionista</td><td>Aprobar la revisión ética del Tribunal de Anclas, confirmando la adhesión a los principios antidepredacionistas y la filosofía simbiótica</td><td>25%</td></tr><tr><td>Dimensión de Contribución</td><td>Contribución a la red simbiótica, al desarrollo de la civilización y al progreso común de las Diez Mil Razas</td><td>El valor de contribución alcanza el nivel del 20% superior de la civilización, con al menos un registro de contribución de nivel civilización</td><td>20%</td></tr><tr><td>Dimensión de Responsabilidad</td><td>Voluntad y capacidad de asumir responsabilidades públicas</td><td>Dispuesto y capaz de asumir responsabilidades públicas por encima del nivel de plano (como mantenimiento de anclas, guardia de la civilización, etc.)</td><td>15%</td></tr></tbody></table><p>El diseño del Sistema de Evaluación de Cuatro Dimensiones encarna la filosofía de evaluación de expertos de la civilización simbiótica de &quot;tener tanto virtud como talento, con la virtud primero&quot;. El poder es solo el fundamento; el carácter, la contribución y la responsabilidad son estándares igualmente indispensables. Un cultivador poderoso pero de carácter maligno que se niega a asumir responsabilidades, incluso si alcanza el nivel de poder del Nivel del Origen, no será reconocido como &quot;Experto Supremo de Planos&quot;, sino que será clasificado como &quot;individuo de alto riesgo&quot; y sometido a supervisión y restricciones correspondientes.</p><h2 id="iii-estandares-detallados-de-la-dimension-de-poder" tabindex="-1">III. Estándares Detallados de la Dimensión de Poder <a class="header-anchor" href="#iii-estandares-detallados-de-la-dimension-de-poder" aria-label="Permalink to &quot;III. Estándares Detallados de la Dimensión de Poder&quot;">​</a></h2><p>La dimensión de poder es el fundamento de la evaluación de Expertos Supremos de Planos; sus estándares detallados incluyen:</p><h3 id="_3-1-estandares-de-nivel" tabindex="-1">3.1 Estándares de Nivel <a class="header-anchor" href="#_3-1-estandares-de-nivel" aria-label="Permalink to &quot;3.1 Estándares de Nivel&quot;">​</a></h3><ul><li>Debe alcanzar el Noveno Nivel &quot;Nivel del Origen&quot; del estándar unificado, tocando las leyes del Origen del universo</li><li>Capaz de movilizar de forma estable el poder del Origen, en lugar de una movilización explosiva ocasional</li><li>El Dao personal se fusiona profundamente con las leyes del Origen del universo, alcanzando el estado de &quot;el Dao es el Origen, el Origen es el Dao&quot;</li></ul><h3 id="_3-2-estandares-de-energia" tabindex="-1">3.2 Estándares de Energía <a class="header-anchor" href="#_3-2-estandares-de-energia" aria-label="Permalink to &quot;3.2 Estándares de Energía&quot;">​</a></h3><ul><li>La energía del Origen almacenada en el cuerpo alcanza el &quot;nivel de plano&quot; — es decir, la energía total es suficiente para sostener el funcionamiento de las leyes básicas de un plano de tamaño mediano</li><li>La pureza de la energía alcanza más del 99%, casi libre de impurezas</li><li>La velocidad de recuperación de energía alcanza la &quot;recuperación instantánea&quot; — incluso después de un consumo masivo en combate, uno puede recuperarse al estado completo en un tiempo extremadamente corto</li></ul><h3 id="_3-3-estandares-de-manipulacion-de-leyes" tabindex="-1">3.3 Estándares de Manipulación de Leyes <a class="header-anchor" href="#_3-3-estandares-de-manipulacion-de-leyes" aria-label="Permalink to &quot;3.3 Estándares de Manipulación de Leyes&quot;">​</a></h3><ul><li>Capaz de movilizar y manipular el poder de las leyes a escala cósmica</li><li>Capaz de participar en el ajuste fino y la optimización de las leyes cósmicas, ejerciendo influencia sustancial sobre el funcionamiento de las leyes</li><li>Capaz de realizar de forma independiente travesía y operaciones entre planos sin apoyo de anclas</li><li>Capaz de crear mundos completos y sistemas de leyes en el Espacio de Aislamiento (capacidad del Nivel de Creación de Mundos)</li></ul><h3 id="_3-4-estandares-de-forma-de-vida" tabindex="-1">3.4 Estándares de Forma de Vida <a class="header-anchor" href="#_3-4-estandares-de-forma-de-vida" aria-label="Permalink to &quot;3.4 Estándares de Forma de Vida&quot;">​</a></h3><ul><li>La forma de vida completa la evolución de alta dimensión, capaz de existir y operar simultáneamente en el plano material, la capa de energía y el dominio de la conciencia</li><li>Casi inmortalidad — los ataques y daños convencionales no pueden constituir una amenaza mortal; solo el poder del mismo nivel o superior puede dañarlo verdaderamente</li><li>Capaz de anclar su impronta de vida en el Origen del universo, capaz de renacer mediante el anclaje al Origen incluso si el cuerpo físico es destruido</li></ul><h2 id="iv-estandares-detallados-de-la-dimension-de-caracter" tabindex="-1">IV. Estándares Detallados de la Dimensión de Carácter <a class="header-anchor" href="#iv-estandares-detallados-de-la-dimension-de-caracter" aria-label="Permalink to &quot;IV. Estándares Detallados de la Dimensión de Carácter&quot;">​</a></h2><p>La dimensión de carácter es la parte más distintiva de la evaluación de expertos de la civilización simbiótica, y la diferencia más fundamental con la era del depredacionismo:</p><h3 id="_4-1-postura-antidepredacionista" tabindex="-1">4.1 Postura Antidepredacionista <a class="header-anchor" href="#_4-1-postura-antidepredacionista" aria-label="Permalink to &quot;4.1 Postura Antidepredacionista&quot;">​</a></h3><ul><li>Respaldar y practicar fundamentalmente el antidepredacionismo, sin ningún antecedente de cultivo depredador jamás</li><li>Incluso en situaciones extremas, nunca elegir el autosocorro a costa de la depredación sobre otros</li><li>Resistir y oponerse activamente a cualquier forma de comportamiento depredador, atreverse a decir no a las fuerzas depredadoras</li></ul><h3 id="_4-2-filosofia-simbiotica" tabindex="-1">4.2 Filosofía Simbiótica <a class="header-anchor" href="#_4-2-filosofia-simbiotica" aria-label="Permalink to &quot;4.2 Filosofía Simbiótica&quot;">​</a></h3><ul><li>Comprender y respaldar profundamente la filosofía central de la civilización de &quot;simbiosis de las Diez Mil Razas, ascensión dimensional del universo&quot;</li><li>Priorizar siempre los intereses simbióticos en el cultivo personal y los asuntos públicos</li><li>Participar activamente en la construcción y mantenimiento de la red simbiótica, dispuesto a compartir los resultados de cultivo personales y el conocimiento con todos los seres vivos</li></ul><h3 id="_4-3-madurez-mental" tabindex="-1">4.3 Madurez Mental <a class="header-anchor" href="#_4-3-madurez-mental" aria-label="Permalink to &quot;4.3 Madurez Mental&quot;">​</a></h3><ul><li>Emocionalmente estable, no dañará la civilización y a todos los seres por emociones personales</li><li>Poseer una visión cósmica grandiosa y una visión histórica de largo plazo, no sacrificando el desarrollo a largo plazo por intereses a corto plazo</li><li>Capaz de soportar enormes presiones y reveses, permaneciendo racional y resuelto en las dificultades</li></ul><h3 id="_4-4-revision-etica" tabindex="-1">4.4 Revisión Ética <a class="header-anchor" href="#_4-4-revision-etica" aria-label="Permalink to &quot;4.4 Revisión Ética&quot;">​</a></h3><p>La evaluación de la dimensión de carácter es ejecutada por el &quot;Comité de Revisión Ética&quot; dependiente del Tribunal de Anclas; los métodos de revisión incluyen:</p><ul><li>Revisión de comportamiento histórico: revisar todos los registros de comportamiento importantes del cultivador a lo largo de la historia</li><li>Escaneo profundo de la conciencia: con el consentimiento voluntario del cultivador, realizar un escaneo profundo a nivel de la conciencia, confirmando sus verdaderos pensamientos internos</li><li>Prueba de estrés situacional: crear dilemas morales extremos en entornos simulados, observando las elecciones del cultivador</li><li>Observación a largo plazo: para candidatos controvertidos, realizar observación y evaluación durante un período de varios años</li></ul><h2 id="v-estandares-detallados-de-la-dimension-de-contribucion" tabindex="-1">V. Estándares Detallados de la Dimensión de Contribución <a class="header-anchor" href="#v-estandares-detallados-de-la-dimension-de-contribucion" aria-label="Permalink to &quot;V. Estándares Detallados de la Dimensión de Contribución&quot;">​</a></h2><p>La dimensión de contribución mide la contribución real del cultivador a la civilización simbiótica y al progreso común de las Diez Mil Razas:</p><h3 id="_5-1-tipos-de-contribucion" tabindex="-1">5.1 Tipos de Contribución <a class="header-anchor" href="#_5-1-tipos-de-contribucion" aria-label="Permalink to &quot;5.1 Tipos de Contribución&quot;">​</a></h3><ul><li><strong>Contribución de cultivo</strong>: efectos ejemplares de avances de nivel, creación de nuevas técnicas, innovación de teorías de cultivo</li><li><strong>Contribución de conocimiento</strong>: compartir públicamente las percepciones de cultivo, trabajos de educación y formación, resultados de investigación académica</li><li><strong>Contribución tecnológica</strong>: innovación de la tecnología de ingeniería de leyes, optimización de la tecnología del Fruto Multiplicador, mejora del hardware de anclas</li><li><strong>Contribución de servicio</strong>: mantenimiento de anclas, gobernanza de la civilización, guía de mentores, coordinación entre razas</li><li><strong>Contribución ecológica</strong>: restauración ecológica planetaria, mejora de la circulación de energía de los planos, protección del medio ambiente cósmico</li><li><strong>Contribución de guardia</strong>: resistir amenazas externas, proteger la seguridad de la civilización, rescatar vidas en desastres</li></ul><h3 id="_5-2-cuantificacion-de-la-contribucion" tabindex="-1">5.2 Cuantificación de la Contribución <a class="header-anchor" href="#_5-2-cuantificacion-de-la-contribucion" aria-label="Permalink to &quot;5.2 Cuantificación de la Contribución&quot;">​</a></h3><p>Los valores de contribución son registrados y calculados automáticamente por la red de anclas; diferentes tipos de contribuciones reciben diferentes pesos según su influencia y valor. El estándar de contribución para Expertos Supremos de Planos es &quot;el valor de contribución alcanza el nivel del 20% superior de la civilización&quot;, y debe haber al menos una &quot;contribución de nivel civilización&quot; — una contribución que haya producido una influencia mayor y profunda en el desarrollo de toda la civilización.</p><h2 id="vi-estandares-detallados-de-la-dimension-de-responsabilidad" tabindex="-1">VI. Estándares Detallados de la Dimensión de Responsabilidad <a class="header-anchor" href="#vi-estandares-detallados-de-la-dimension-de-responsabilidad" aria-label="Permalink to &quot;VI. Estándares Detallados de la Dimensión de Responsabilidad&quot;">​</a></h2><p>La dimensión de responsabilidad mide la voluntad y capacidad del cultivador para asumir responsabilidades públicas:</p><h3 id="_6-1-tipos-de-responsabilidad" tabindex="-1">6.1 Tipos de Responsabilidad <a class="header-anchor" href="#_6-1-tipos-de-responsabilidad" aria-label="Permalink to &quot;6.1 Tipos de Responsabilidad&quot;">​</a></h3><p>Las responsabilidades públicas que los Expertos Supremos de Planos deben asumir incluyen:</p><ul><li><strong>Guardia de anclas</strong>: ser responsable de la guardia y mantenimiento de una o más anclas avanzadas</li><li><strong>Consejero de la civilización</strong>: servir como consejero del más alto nivel de la civilización, participando en decisiones sobre la dirección del desarrollo de la civilización</li><li><strong>Herencia de mentores</strong>: formar y guiar a la próxima generación de cultivadores, especialmente candidatos semilla con potencial para alcanzar los niveles supremos</li><li><strong>Patrulla de planos</strong>: patrullar regularmente los planos, monitoreando la estabilidad de los planos y el desarrollo de la civilización</li><li><strong>Respuesta a crisis</strong>: emprender las tareas de respuesta más centrales cuando la civilización enfrenta crisis mayores (como el colapso de planos, la invasión externa, etc.)</li><li><strong>Participación en leyes</strong>: participar en el ajuste fino y la optimización de las leyes cósmicas, contribuyendo a la ascensión dimensional general del universo</li></ul><h3 id="_6-2-formas-de-asumir-responsabilidades" tabindex="-1">6.2 Formas de Asumir Responsabilidades <a class="header-anchor" href="#_6-2-formas-de-asumir-responsabilidades" aria-label="Permalink to &quot;6.2 Formas de Asumir Responsabilidades&quot;">​</a></h3><p>Los Expertos Supremos de Planos pueden elegir los tipos de responsabilidad a priorizar según sus intereses y fortalezas, pero no pueden negarse completamente a asumir responsabilidades públicas. La civilización simbiótica implementa el &quot;sistema de obligación de los fuertes&quot; — los cultivadores que alcanzan el nivel de Experto Supremo de Planos tienen la obligación de usar parte de su poder para los asuntos públicos. La obligación específica es invertir al menos el 30% de su tiempo y energía en responsabilidades públicas cada año.</p><h2 id="vii-la-estrategia-de-activacion-del-20" tabindex="-1">VII. La Estrategia de Activación del 20% <a class="header-anchor" href="#vii-la-estrategia-de-activacion-del-20" aria-label="Permalink to &quot;VII. La Estrategia de Activación del 20%&quot;">​</a></h2><p>La &quot;Estrategia de Activación del 20%&quot; es una de las estrategias centrales de la Civilización Simbiótica del Ancla en su etapa inicial; su objetivo es activar, dentro de la primera era tras el establecimiento de la civilización, al 20% de todos los seres vivos para que alcancen el nivel de Experto Supremo de Planos.</p><h3 id="_7-1-objetivos-estrategicos" tabindex="-1">7.1 Objetivos Estratégicos <a class="header-anchor" href="#_7-1-objetivos-estrategicos" aria-label="Permalink to &quot;7.1 Objetivos Estratégicos&quot;">​</a></h3><ul><li>Objetivo a corto plazo (dentro de 100 años del establecimiento de la civilización): activar al 1% de todos los seres vivos para alcanzar el Nivel del Origen</li><li>Objetivo a mediano plazo (dentro de 500 años): activar al 10% de todos los seres vivos para alcanzar el Nivel del Origen</li><li>Objetivo a largo plazo (dentro de 1000 años): activar al 20% de todos los seres vivos para alcanzar el Nivel del Origen</li></ul><h3 id="_7-2-apoyo-estrategico" tabindex="-1">7.2 Apoyo Estratégico <a class="header-anchor" href="#_7-2-apoyo-estrategico" aria-label="Permalink to &quot;7.2 Apoyo Estratégico&quot;">​</a></h3><p>La implementación de la Estrategia de Activación del 20% depende de las siguientes condiciones de apoyo:</p><ul><li><strong>Apertura de los Trescientos Sistemas</strong>: proporcionar ricas opciones de caminos de cultivo para todos los seres vivos</li><li><strong>Popularización de la Tecnología del Fruto Multiplicador</strong>: la amplificación centupla de deducción de cultivo mejora enormemente la eficiencia del cultivo</li><li><strong>Sistema de Contrato Vinculado a la Producción</strong>: proporcionar apoyo de recursos estable a los cultivadores</li><li><strong>Sistema de seguridad Un Camino para Todos</strong>: asegurar que cada vida tenga condiciones básicas de cultivo</li><li><strong>Red de mentores</strong>: los cultivadores avanzados guían a los cultivadores principiantes, acelerando la formación de talentos</li></ul><h3 id="_7-3-significado-estrategico" tabindex="-1">7.3 Significado Estratégico <a class="header-anchor" href="#_7-3-significado-estrategico" aria-label="Permalink to &quot;7.3 Significado Estratégico&quot;">​</a></h3><p>El significado de la Estrategia de Activación del 20% no reside solo en formar un gran número de expertos, sino también en:</p><ul><li>Proporcionar una base de poder suficiente para la ascensión dimensional general del universo</li><li>Establecer un enorme grupo de expertos, evitando el monopolio de poder de expertos individuales</li><li>Formar una atmósfera de civilización de &quot;expertos que emergen en sucesión&quot;, inspirando a más vidas a cultivar diligentemente</li><li>Proporcionar una base amplia de expertos para la República de las Diez Mil Razas, asegurando que cada raza tenga sus propios representantes supremos</li></ul><h2 id="viii-derechos-y-tratamiento-de-los-expertos-supremos-de-planos" tabindex="-1">VIII. Derechos y Tratamiento de los Expertos Supremos de Planos <a class="header-anchor" href="#viii-derechos-y-tratamiento-de-los-expertos-supremos-de-planos" aria-label="Permalink to &quot;VIII. Derechos y Tratamiento de los Expertos Supremos de Planos&quot;">​</a></h2><p>Como retribución por sus responsabilidades, los Expertos Supremos de Planos disfrutan de los siguientes derechos y tratamiento:</p><ul><li><strong>Prioridad de recursos</strong>: disfrutar de la más alta prioridad en la asignación de recursos de cultivo</li><li><strong>Derecho de participación en leyes</strong>: tener derecho a participar en las decisiones sobre el ajuste fino y la optimización de las leyes cósmicas</li><li><strong>Derecho de creación de espacios</strong>: tener derecho a crear sus propios espacios o mundos independientes</li><li><strong>Derecho de decisión de la civilización</strong>: tener escaños y derechos de voto en el órgano de decisión más alto de la civilización</li><li><strong>Derecho de paso entre planos</strong>: disfrutar de derechos de libre paso en todos los planos controlados por la civilización simbiótica</li><li><strong>Honor y reverencia</strong>: recibir el respeto y la reverencia de toda la civilización, con sus hazañas consignadas en los anales de la civilización</li></ul><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>Los estándares de Expertos Supremos de Planos son la redefinición por parte de la Civilización Simbiótica del Ancla del concepto de &quot;los fuertes&quot;. En la civilización simbiótica, los fuertes no son saqueadores, no son señores, no son gobernantes por encima de todo, sino guardianes, servidores y guías. La dimensión de poder es el fundamento, la dimensión de carácter es el alma, la dimensión de contribución es el valor y la dimensión de responsabilidad es el compromiso — solo cuando las cuatro dimensiones están unidas se es un verdadero &quot;Experto Supremo de Planos&quot;. El objetivo de la Estrategia de Activación del 20% no es solo formar al 20% de expertos, sino formar al 20% de guardianes dispuestos a asumir la responsabilidad de la simbiosis de las Diez Mil Razas y la ascensión dimensional del universo. Cuando el 20% de todos los seres vivos alcancen el nivel de Experto Supremo de Planos y practiquen la filosofía simbiótica, la ascensión dimensional general del universo ya no será un sueño lejano.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>14-修炼境界统一划分 (División Unificada de los Niveles de Cultivo)</li><li>23-20%激活战略规划 (Plan de la Estrategia de Activación del 20%)</li><li>19-修炼伦理与边界 (Ética y Límites del Cultivo)</li></ul>',61)])])}const v=a(n,[["render",l]]);export{m as __pageData,v as default};
